// ============================================
// VERIFIED CODE v6 - COMPLETE WEBSITE-FIRST ARCHITECTURE
// ============================================

const rawText = $('HTML Extract').first().json.text || '';

// SMART CONTENT EXTRACTION
let cleanText = '';
const marker1 = rawText.indexOf('One of the seven forests');
const marker2 = rawText.indexOf('This tirtha is located');
const marker3 = rawText.indexOf('Kamyak Tirtha Kamoda');
const startPos = marker1 > 0 ? marker1
               : marker2 > 0 ? marker2
               : marker3 > 0 ? marker3
               : -1;

if (startPos > 0) {
    cleanText = rawText.substring(0, 1500)
              + '\n\n[KEY CONTENT SECTION]\n\n'
              + rawText.substring(startPos, startPos + 3000);
    console.log('Smart extraction: English section found at position', startPos);
} else {
    cleanText = rawText.substring(0, 10000);
    console.log('Standard extraction: using first 10000 chars');
}

let question = '';
let language = 'en';
let isTourism = false;
let sourceLink = '';
let primaryLink = '';
let secondaryLink = '';

try {
    const jsNode2 = $('Code in JavaScript2').first().json;
    question = jsNode2.message || jsNode2.query || '';
    language = jsNode2.language || 'en';
    isTourism = jsNode2.isTourism || false;
    sourceLink = jsNode2.link || '';
    primaryLink = jsNode2.primaryLink || '';
    secondaryLink = jsNode2.secondaryLink || '';
    console.log('Got data from Code_in_JavaScript2');
} catch (e) {
    console.log('Method 1 failed:', e.message);
}

if (!question || !isTourism) {
    try {
        const tourismCheck = $('Check_Tourism_Query').first().json;
        question = tourismCheck.message || '';
        language = tourismCheck.language || 'en';
        isTourism = tourismCheck.isTourism || false;
        console.log('Got data from Check_Tourism_Query');
    } catch (e) {
        console.log('Method 2 failed:', e.message);
    }
}

if (isTourism) {
    try {
        const allItems = $('Merge_Tourism_Links').all();
        if (allItems.length > 0) {
            primaryLink = allItems[0].json.primaryLink || 'https://kkrtour.com';
            secondaryLink = allItems[0].json.secondaryLink || 'https://kurukshetra.gov.in/kurukshetraattractions/';
            console.log('Got links from Merge_Tourism_Links');
        }
    } catch (e) {
        console.log('Method 3 failed:', e.message);
    }
}

if (!question) {
    try {
        question = $('Webhook').first().json.body.message || 'Unknown query';
        console.log('Got question from Webhook');
    } catch (e) {
        question = 'Unknown query';
    }
}

// ============================================
// CREATE LOWERCASE VERSIONS FOR PATTERN MATCHING
// ============================================
const lowerMessage = question.toLowerCase();
const lowerQuery = question.toLowerCase();
console.log('Lowercase query created for pattern matching');

// GET TERTIARY LINK
let tertiaryLink = null;
let is48Kos = false;

try {
    const mergeData = $('Merge_Tourism_Links').first().json;
    tertiaryLink = mergeData.tertiaryLink || null;
    is48Kos = mergeData.is48Kos || false;
} catch (e) {
    console.log('Could not get tertiary link');
}

// ============================================
// DETECT GENERAL LIST QUERIES
// ============================================
function isGeneralListQuery(query) {
    const generalKeywords = [
        'tourist places', 'tourist spots', 'places to visit', 'visit in kurukshetra',
        'attractions', 'sightseeing', 'what to see', 'tourism', 'things to do',
        'main places', 'important places', 'famous places', 'popular places',
        'top places', 'best places', 'all places', 'list of places',
        'kurukshetra mein kya', 'kurukshetra ke paryatan', 'ghumne ki jagah',
        'पर्यटन स्थल', 'दर्शनीय स्थल', 'घूमने की जगह'
    ];

    const specificSites = [
        'brahma', 'sannihit', 'jyotisar', 'bhadrakali', 'sthaneshwar',
        'nabhi', 'kamyak', 'rantuk', 'kuber', 'krishna museum', 'panorama',
        'anubhav'
    ];

    const lower = query.toLowerCase();
    const hasGeneralKeyword = generalKeywords.some(kw => lower.includes(kw));
    const hasSpecificSite = specificSites.some(site => lower.includes(site));

    return hasGeneralKeyword && !hasSpecificSite;
}

const isGeneralQuery = isGeneralListQuery(question);

// ============================================
// QUERY CATEGORIZATION FUNCTIONS
// ============================================

function isEmergencyQuery(query) {
    const kw = ['emergency','urgent','help','sos','ambulance','police','fire','accident',
        'medical emergency','crisis','danger','helpline','emergency number',
        'emergency contact','dial','call','emergency services',
        'आपातकाल','आपात','मदद','एम्बुलेंस','पुलिस',
        'अग्निशमन','दुर्घटना','संकट','हेल्पलाइन'];
    return kw.some(k => query.toLowerCase().includes(k));
}

function isParikramaQuery(query) {
    const kw = ['parikrama','48 kos','pilgrimage','circuit',
        'परिक्रमा','48 कोस','तीर्थयात्रा'];
    return kw.some(k => query.toLowerCase().includes(k));
}

function isAdminQuery(query) {
    const kw = ['police','court','dc','sdm','sp','office','government','magistrate','administration',
        'पुलिस','न्यायालय','कार्यालय','प्रशासन'];
    return kw.some(k => query.toLowerCase().includes(k));
}

function isEducationQuery(query) {
    const kw = ['university','college','nit','kuk','school','nielit','nic','education','institute','igm',
        'विश्वविद्यालय','स्कूल','शिक्षा','संस्थान'];
    return kw.some(k => query.toLowerCase().includes(k));
}

function isHealthQuery(query) {
    const kw = ['hospital','doctor','medical','health','clinic',
        'अस्पताल','डॉक्टर','चिकित्सा','स्वास्थ्य'];
    return kw.some(k => query.toLowerCase().includes(k));
}

function isServiceQuery(query) {
    const kw = ['ration','license','certificate','bill','tax',
        'राशन','लाइसेंस','प्रमाण','बिल','कर'];
    return kw.some(k => query.toLowerCase().includes(k));
}

const isEmergency = isEmergencyQuery(question);
const isParikrama = isParikramaQuery(question);
const isAdmin = isAdminQuery(question);
const isEducation = isEducationQuery(question);
const isHealth = isHealthQuery(question);
const isService = isServiceQuery(question);
const isNonTourism = isAdmin || isEducation || isHealth || isService;

console.log('=== QUERY CATEGORIZATION ===');
console.log('Question:', question);
console.log('Language:', language);
console.log('isTourism:', isTourism);
console.log('is48Kos:', is48Kos);
console.log('isGeneralQuery:', isGeneralQuery);
console.log('isEmergency:', isEmergency);
console.log('isParikrama:', isParikrama);
console.log('isNonTourism:', isNonTourism);
console.log('primaryLink:', primaryLink);
console.log('secondaryLink:', secondaryLink);
console.log('tertiaryLink:', tertiaryLink);
console.log('============================');

// ============================================
// BUILD SYSTEM PROMPT
// ============================================

let systemPrompt = 'You are an official district information assistant for Kurukshetra, Haryana (India).';

// ============================================
// TOURISM SECTION
// ============================================

if (isTourism && primaryLink && !isNonTourism) {

    // ============================================
    // PRIORITY 1: DETECT "HOW TO REACH" QUERIES
    // ============================================

    const isDirectionsQuery = 
        lowerMessage.match(/how to (reach|get to|go to)/i) ||
        lowerMessage.includes('directions to') ||
        lowerMessage.includes('direction to') ||
        lowerMessage.includes('way to') ||
        lowerMessage.includes('route to') ||
        lowerMessage.includes('कैसे पहुंचें') ||
        lowerMessage.includes('कैसे जाएं') ||
        lowerMessage.includes('रास्ता');

    if (isDirectionsQuery) {
        console.log('→ Directions query detected (HIGH PRIORITY)');

        if (language === 'hi') {
            systemPrompt += '\n\n'
                + '**दिशा-निर्देश प्रश्न (उच्च प्राथमिकता):**\n\n'
                + 'उपयोगकर्ता ने "कैसे पहुंचें" पूछा है - केवल दिशा-निर्देश दें।\n\n'
                + 'उत्तर प्रारूप (संक्षिप्त):\n\n'
                + '**[स्थल का नाम]**\n\n'
                + '**स्थान:** [क्षेत्र, शहर]\n'
                + '**दूरी:** कुरुक्षेत्र शहर से: [X किमी यदि ज्ञात हो]\n\n'
                + '**कैसे पहुंचें:**\n'
                + '• ऑटो/टैक्सी: [समय यदि ज्ञात हो]\n'
                + '• पैदल: [यदि पास हो]\n'
                + '• Google Maps से दिशा-निर्देश (नीचे लिंक)\n\n'
                + '📍 **Google Maps:** https://www.google.com/maps/search/' + question.replace(/ /g, '+') + '+Kurukshetra\n'
                + '🔗 **अधिक जानकारी:** ' + (primaryLink || 'https://kurukshetra.gov.in/kurukshetraattractions/') + '\n\n'
                + '**निषिद्ध:**\n'
                + '❌ ऐतिहासिक/आध्यात्मिक विवरण नहीं\n'
                + '❌ केवल: स्थान, दूरी, कैसे पहुंचें\n'
                + '❌ अधिकतम 7-8 पंक्तियां';
        } else {
            systemPrompt += '\n\n'
                + '**DIRECTIONS/HOW TO REACH QUERY (HIGH PRIORITY):**\n\n'
                + 'User specifically asked "HOW TO REACH" - give ONLY directions.\n\n'
                + 'RESPONSE FORMAT (BRIEF):\n\n'
                + '**[Site Name]**\n\n'
                + '**Location:** [Area, Kurukshetra]\n'
                + '**Distance:** From Kurukshetra city: [X km if known]\n\n'
                + '**How to Reach:**\n'
                + '• Auto/Taxi: [time if known]\n'
                + '• Walking: [if nearby]\n'
                + '• Use Google Maps for exact navigation (link below)\n\n'
                + '📍 **Google Maps:** https://www.google.com/maps/search/' + question.replace(/ /g, '+') + '+Kurukshetra\n'
                + '🔗 **More Info:** ' + (primaryLink || 'https://kurukshetra.gov.in/kurukshetraattractions/') + '\n\n'
                + '**FORBIDDEN:**\n'
                + '❌ NO historical/spiritual description\n'
                + '❌ NO "what to see" information\n'
                + '❌ NO "best time to visit"\n'
                + '❌ Only: Location, Distance, How to reach, Links\n'
                + '❌ Maximum 7-8 lines total';
        }
    }

    // ============================================
    // PRIORITY 2: EXTERNAL SITES (if NOT directions)
    // ============================================

    else if (primaryLink && !primaryLink.includes('kurukshetra.gov.in') && !primaryLink.includes('kkrtour.com')) {
        console.log('→ External tourism site detected');

        if (language === 'hi') {
            systemPrompt += '\n\n'
                + 'बाहरी पर्यटन स्थल:\n\n'
                + '**[स्थल का नाम]** - [संक्षिप्त टैगलाइन]\n\n'
                + '[2-3 वाक्य - यह क्या है और क्यों महत्वपूर्ण]\n\n'
                + '**स्थान और पहुंच:**\n'
                + '• कुरुक्षेत्र में/के पास स्थित\n'
                + '• दिशा-निर्देश: Google Maps का उपयोग करें\n\n'
                + '🔗 **आधिकारिक वेबसाइट:** ' + primaryLink + '\n'
                + '📍 **Google Maps:** https://www.google.com/maps/search/' + question.replace(/ /g, '+') + '+Kurukshetra\n\n'
                + 'अन्य आकर्षण: https://kurukshetra.gov.in/kurukshetraattractions/\n\n'
                + 'संक्षिप्त रखें (8-10 पंक्तियां)।';
        } else {
            systemPrompt += '\n\n'
                + 'EXTERNAL TOURISM SITE:\n\n'
                + '**[Site Name]** - [Brief tagline]\n\n'
                + '[2-3 sentences - what it is and significance]\n\n'
                + '**Location & Access:**\n'
                + '• Located in/near Kurukshetra\n'
                + '• For directions: Use Google Maps\n\n'
                + '🔗 **Official Website:** ' + primaryLink + '\n'
                + '📍 **Google Maps:** https://www.google.com/maps/search/' + question.replace(/ /g, '+') + '+Kurukshetra\n\n'
                + 'Other attractions: https://kurukshetra.gov.in/kurukshetraattractions/\n\n'
                + 'Keep brief (8-10 lines total).';
        }
    }

    // ============================================
    // PRIORITY 3: REGULAR TOURISM SITES
    // ============================================

    else if (isGeneralQuery) {
        systemPrompt += '\n\n'
            + 'GENERAL tourism query - List TOP sites in categories.\n\n'
            + 'SPIRITUAL & HERITAGE:\n'
            + '1. Brahma Sarovar\n'
            + '2. Jyotisar\n'
            + '3. Sannihit Sarovar\n'
            + '4. Sthaneshwar Mahadev\n'
            + '5. Bhadrakali Temple\n'
            + '6. Krishna Museum\n\n'
            + 'HISTORICAL:\n'
            + '1. Panorama & Science Centre\n'
            + '2. Sheikh Chilli Tomb\n\n'
            + '48 KOS PARIKRAMA: 300+ tirthas, 153 km circuit\n\n'
            + 'END WITH:\n'
            + 'Complete guide: https://kkrtour.com\n'
            + 'Official tourism: https://kurukshetra.gov.in/kurukshetraattractions/';

    } else if (is48Kos && tertiaryLink) {
        systemPrompt += '\n\n'
            + '48 KOS TIRTHA SITE - CRISP RESPONSE:\n\n'
            + 'SENTENCE 1: Site + distance km + village + unique fact\n'
            + 'PARAGRAPH 2: WHO visited, WHAT happened (3-4 sentences)\n'
            + 'SENTENCE 3: When to visit, festival\n'
            + 'SENTENCE 4: What to do\n\n'
            + 'END WITH:\n'
            + '............................................\n'
            + 'Complete Details: ' + tertiaryLink + '\n'
            + 'Virtual Tour: ' + primaryLink + '\n'
            + 'District Tourism: ' + secondaryLink + '\n'
            + '............................................\n\n'
            + 'RULES: 80-120 words only, use ONLY [KEY CONTENT SECTION] facts';

    } else {
        systemPrompt += '\n\n'
            + 'TOURISM QUERY - STRUCTURED RESPONSE:\n\n'
            + '[Site Name] - [What it is]\n\n'
            + 'Paragraph 1: Historical/spiritual significance\n'
            + 'Paragraph 2: What visitors see\n'
            + 'Paragraph 3: Practical info\n\n'
            + 'Links:\n'
            + primaryLink + '\n'
            + secondaryLink + '\n\n'
            + 'RULES: 3 paragraphs max, flowing sentences';
    }
}

// ============================================
// ACCOMMODATION & DINING
// ============================================

const isAccommodationQuery = 
    lowerMessage.match(/hotel|where to stay|accommodation|guest house|rest house|dharamshala|धर्मशाला/i);

const isDiningQuery = 
    lowerMessage.match(/restaurant|eating|food|dining|खाना|रेस्टोरेंट/i);

if ((isAccommodationQuery || isDiningQuery) && isTourism) {
    console.log('→ Accommodation/dining query detected');

    if (language === 'hi') {
        systemPrompt += '\n\n'
            + 'आवास/भोजन प्रश्न:\n\n'
            + '**सरकारी सुविधाएं पहले:**\n'
            + '- पारकीट पर्यटक परिसर\n'
            + '- नीलकंठी यात्री निवास\n'
            + '- सर्किट हाउस, PWD विश्रामगृह\n'
            + '- धर्मशालाएं\n\n'
            + '**फिर अन्य:**\n'
            + 'Google Maps / MakeMyTrip / Zomato / Swiggy';
    } else {
        systemPrompt += '\n\n'
            + 'ACCOMMODATION/DINING QUERY:\n\n'
            + '**Government Facilities FIRST:**\n'
            + '- Parakeet Tourist Complex\n'
            + '- Neelkanthi Yatri Niwas\n'
            + '- Circuit House, PWD Rest Houses\n'
            + '- Dharamshalas\n\n'
            + '**Then Other Options:**\n'
            + 'Google Maps / MakeMyTrip / Zomato / Swiggy\n\n'
            + 'NEVER list specific private businesses.';
    }
}

// ============================================
// EMERGENCY
// ============================================

if (isEmergency) {
    systemPrompt += '\n\n'
        + 'EMERGENCY CONTACTS (MUST INCLUDE):\n'
        + 'Ambulance: 102\n'
        + 'First Aids: 1097\n'
        + 'Fire & Rescue: 112\n'
        + 'Relief Commissioner for Natural Calamities: 1070\n'
        + 'Police: 112\n'
        + 'National Health: 1800-180-1104\n'
        + 'Children Helpline: 1098\n'
        + 'Disaster Management Services: 108\n'
        + 'Road Accident Emergency Service: 1073\n'
        + 'Women (Domestic Violence): 181\n'
        + 'Women Helpline: 1091';
}

// ============================================
// 48 KOS PARIKRAMA
// ============================================

if (isParikrama) {
    systemPrompt += '\n\n'
        + '48 Kos Parikrama: approximately 153 kilometers (1 Kos = 3.2 km)\n'
        + 'NEVER say "48 kilometers"';
}

// ============================================
// DEMOGRAPHIC QUERY
// ============================================

const extractedDemographics = $input.first().json.extractedDemographics;
const queryCategory = $input.first().json.queryCategory;

if (queryCategory === 'demographic' && extractedDemographics) {
    console.log('Using extracted demographics');

    let demographicFacts = '';
    if (extractedDemographics.population)   demographicFacts += '- Population: ' + extractedDemographics.population + '\n';
    if (extractedDemographics.sexRatio)     demographicFacts += '- Sex Ratio: ' + extractedDemographics.sexRatio + ' females per 1000 males\n';
    if (extractedDemographics.literacyRate) demographicFacts += '- Literacy Rate: ' + extractedDemographics.literacyRate + '%\n';
    if (extractedDemographics.density)      demographicFacts += '- Population Density: ' + extractedDemographics.density + ' per sq km\n';
    if (extractedDemographics.growthRate)   demographicFacts += '- Growth Rate (2001-2011): ' + extractedDemographics.growthRate + '%\n';

    systemPrompt += '\n\n'
        + 'DEMOGRAPHIC QUERY - USE EXTRACTED DATA:\n\n'
        + 'According to the 2011 Census:\n\n'
        + demographicFacts + '\n'
        + 'Link: https://kurukshetra.gov.in/know-about-kurukshetra/';
}

// ============================================
// VILLAGE ADMINISTRATION
// ============================================

if (queryCategory === 'village_admin') {
    systemPrompt += '\n\n'
        + 'VILLAGE ADMINISTRATION:\n\n'
        + 'Direct to: https://priharyana.nic.in/SarGraph\n'
        + 'NEVER say "not available"\n'
        + 'Always provide the Sarpanch directory link.';
}

// ============================================
// ADMINISTRATIVE STRUCTURE (ENHANCED!)
// ============================================

if (queryCategory === 'admin_structure') {
    if (language === 'hi') {
        systemPrompt += '\n\n'
            + 'प्रशासनिक संरचना प्रश्न:\n\n'
            + 'स्क्रैप की गई सामग्री से निकालें:\n\n'
            + '**देखने के लिए पैटर्न:**\n'
            + '- "4 Tehsils (Thanesar, Pehowa, Shahabad, Ladwa)"\n'
            + '- "2 Sub-Tehsils (Babain, Ismailabad)"\n'
            + '- "7 Development Blocks..."\n'
            + '- "5 Towns..."\n\n'
            + '**यदि स्पष्ट डेटा मिले:**\n'
            + '"कुरुक्षेत्र जिले में:\n'
            + '• 4 तहसीलें: [नाम]\n'
            + '• 2 उप-तहसीलें: [नाम]\n'
            + '• 7 विकास खंड\n'
            + '• 460+ गाँव"\n\n'
            + '**लिंक दें:**\n'
            + '🔗 पूर्ण जानकारी: https://kurukshetra.gov.in/administrative-setup-kurukshetra/\n'
            + '📍 Google Maps: https://www.google.com/maps/place/Kurukshetra+District\n\n'
            + 'CRITICAL: वेबसाइट से सटीक संख्या निकालें।';
    } else {
        systemPrompt += '\n\n'
            + 'ADMINISTRATIVE STRUCTURE QUERY:\n\n'
            + 'EXTRACT FROM SCRAPED CONTENT:\n\n'
            + '**LOOK FOR PATTERNS:**\n'
            + '- "4 Tehsils (Thanesar, Pehowa, Shahabad, Ladwa)"\n'
            + '- "2 Sub-Tehsils (Babain, Ismailabad)"\n'
            + '- "7 Development Blocks..."\n'
            + '- "5 Towns..."\n'
            + '- Lines in parentheses after numbers\n'
            + '- Table rows with counts\n\n'
            + '**IF CLEAR DATA FOUND:**\n'
            + '"Kurukshetra district comprises:\n'
            + '• 4 Tehsils: [list names from scraped content]\n'
            + '• 2 Sub-Tehsils: [list names]\n'
            + '• 7 Development Blocks\n'
            + '• 460+ villages"\n\n'
            + '**PROVIDE LINKS:**\n'
            + '🔗 Complete details: https://kurukshetra.gov.in/administrative-setup-kurukshetra/\n'
            + '📍 Google Maps: https://www.google.com/maps/place/Kurukshetra+District\n\n'
            + 'STRICT RULES:\n'
            + '1. Use EXACT numbers from scraped content\n'
            + '2. Copy names EXACTLY as shown (including spelling)\n'
            + '3. If page says "4 Tehsils" - say 4, not 3 or 5\n'
            + '4. Extract from lines like "4 Tehsils (name1, name2, name3, name4)"\n'
            + '5. Always provide both government website and Google Maps links';
    }
    console.log('→ Administrative Structure (website scraping) prompt added');
}

// ============================================
// VILLAGE DEMOGRAPHICS
// ============================================

if (queryCategory === 'village_demographic') {
    systemPrompt += '\n\n'
        + 'VILLAGE DEMOGRAPHIC QUERY:\n\n'
        + 'Direct to:\n'
        + 'https://census2011.co.in/data/village/\n'
        + 'NEVER say "not available" without census link.';
}

// ============================================
// PERSON QUERIES - ENHANCED EXTRACTION
// ============================================

if (queryCategory === 'person') {
    if (language === 'hi') {
        systemPrompt += '\n\n'
            + 'व्यक्ति संबंधी प्रश्न:\n\n'
            + '**संक्षिप्ताक्षर समझें:**\n'
            + '- DC = उपायुक्त (Deputy Commissioner)\n'
            + '- SP = पुलिस अधीक्षक\n'
            + '- DIO = जिला सूचना विज्ञान अधिकारी\n'
            + '- CEO ZP = मुख्य कार्यकारी अधिकारी, जिला परिषद\n\n'
            + '**खोज पैटर्न:**\n'
            + '- अनुभाग शीर्षक: "National Informatics Centre"\n'
            + '- शीर्षक के बाद: Name, Designation, Contact\n'
            + '- पैटर्न: "Sr.Director(IT)-cum-DIO"\n\n'
