function normalizeForMatching(text) {
    return text
        .toLowerCase()
        .replace(/[_\-\s]+/g, ' ')          // hyphens/underscores/spaces → single space
        .replace(/[^a-z0-9\s\u0900-\u097F]/g, '') // remove special chars (keep Devanagari Unicode)
        .trim();
}

    // Helper: check if words match (handles partial matches)
    function wordsMatch(word1, word2) {
        // Exact match
        if (word1 === word2) return true;

        // One contains the other (min 4 chars to avoid false positives)
        if (word1.length >= 4 && word2.length >= 4) {
            if (word1.includes(word2) || word2.includes(word1)) return true;
        }

        // First 5 chars match (for spelling variations like machkrur/machkruk)
        if (word1.length >= 5 && word2.length >= 5) {
            if (word1.substring(0, 5) === word2.substring(0, 5)) return true;
        }

        return false;
    }

