if (!primaryLink || !primaryLink.startsWith('http')) {
    primaryLink = 'https://kkrtour.com/viewall.html';
}
if (!secondaryLink || !secondaryLink.startsWith('http')) {
    secondaryLink = 'https://kurukshetra.gov.in/kurukshetraattractions/';
}

console.log('=== FINAL LINKS ===');
console.log('Primary:', primaryLink);
console.log('Secondary:', secondaryLink);
console.log('Tertiary:', tertiaryLink || 'none');

// RETURN
return [{
    json: {
        message: message,
        language: language,
        isTourism: true,
        isBroadTourism: isBroad,
        primaryLink: primaryLink,
        secondaryLink: secondaryLink,
        tertiaryLink: tertiaryLink || null,
        is48Kos: !!tertiaryLink,
        noResults: false,
        organic_results: govtResult.organic_results || []
    }
}];

