const searchResult = $input.first().json;
const message = $('Check_Tourism_Query').first().json.message;
const language = $('Check_Tourism_Query').first().json.language;

// Get query category
let queryCategory = 'general';
try {
    queryCategory = $('Smart_Query_Enhancer').first().json.queryCategory || 'general';
} catch (e) {
    console.log('Could not get queryCategory');
}

// ============================================
// DEMOGRAPHIC QUERIES - HARDCODE LINK
// ============================================
let finalResults = searchResult.organic_results || [];

if (queryCategory === 'demographic') {
    console.log('→ Demographic query detected - using hardcoded know-about link');

    // Replace search results with hardcoded know-about page
    finalResults = [{
        link: 'https://kurukshetra.gov.in/know-about-kurukshetra/',
        title: 'Know Kurukshetra - Demographics',
        snippet: 'Official demographic information for Kurukshetra district'
    }];
}

return [{
    json: {
        message: message,
        language: language,
        isTourism: false,
        queryCategory: queryCategory,
        organic_results: finalResults
    }
}];

const data = $input.first().json;
const message = data.body?.message || data.message || '';
const language = data.body?.language || data.language || 'en';

console.log('=== Check Tourism Query ===');
console.log('Input message:', message);


// ============================================
// TOURISM DETECTION
// ============================================

const tourismKeywordsEn = [
    // General tourism
    'tourist', 'tourism', 'temple', 'mandir', 'tirath', 'tirtha', 'yaksh', 'yaksha',
   'visit', 'sightseeing', 'places to see', 'things to do',
    'sacred', 'holy', 'site', 'place',
    // Specific sites
    'brahma', 'sarovar', 'jyotisar', 'jyoti sar', 'sthaneshwar', 'sthaneswar',
      'sheikh chilli',
    // Institutions
    'kalpana chawla', 'planetarium',
    'kurukshetra university', 'panorama', 'memorial', 'historical', 'monument',
    'anubhav', 'kendra', 'experience'
];

const tourismKeywordsHi = [
    'पर्यटन', 'मंदिर', 'तीर्थ', 'दर्शनीय', 'स्थल', 'यक्ष',
      'बाण गंगा', 'सन्निहित', 'कर्ण', 'भीष्म',
    'घूमने', 'अनुभव', 'केंद्र'
];

const allKeywords = [...tourismKeywordsEn, ...tourismKeywordsHi];
const lowerMessage = message.toLowerCase();

const isTourism = allKeywords.some(kw => lowerMessage.includes(kw));

console.log('Is Tourism Query:', isTourism);


// ============================================
// PRIVATE BUSINESS DETECTION - ENHANCED
// ============================================

const privateBusinessKeywords = [
    // Food - REMOVED: 'restaurant', 'hotel' (now on govt tourism pages)
    'pizza', 'burger', 'chinese', 'italian', 'mexican', 'fast food',
    'dhaba', 'eatery', 'food joint',
    'best pizza', 'best burger', 'best restaurant', 'best food',
    'where to eat', 'food delivery', 'home delivery',

    // Accommodation - REMOVED: 'hotel', 'guest house' (govt tourism)
    'pg', 'paying guest', 'hostel private', 'flat for rent',

    // Commercial establishments
    'shop', 'store', 'market', 'grocery', 'supermarket', 'mall',
    'lawyer private', 'advocate private', 'ca private',
    'real estate agent', 'property dealer',


    // Hindi
    'दुकान', 'बाज़ार', 'किराना', 'कैफे', 'माल', 'जिम', 'सैलून',
    'पिज्जा', 'बर्गर', 'कोचिंग', 'ट्यूशन'
];

const isPrivateBusiness = privateBusinessKeywords.some(kw => 
    lowerMessage.includes(kw)
);

console.log('Is Private Business Query:', isPrivateBusiness);


// ============================================
// PERSPECTIVE/THEME DETECTION (NEW!)
// ============================================

const perspectiveKeywords = {
  historical: ['historical', 'history', 'ancient', 'archaeological', 'through the ages', 'heritage', 'civilization', 'इतिहास', 'पुरातात्विक'],
    hindu: ['hindu', 'mahabharata', 'mahabharat', 'krishna', 'geeta', 'gita', 'हिंदू', 'महाभारत', 'कृष्ण', 'गीता']

};

let detectedPerspective = 'general';  // default

// Check for perspective matches (most specific first)
for (const [perspective, keywords] of Object.entries(perspectiveKeywords)) {
    if (keywords.some(kw => lowerMessage.includes(kw))) {
        detectedPerspective = perspective;
        console.log(`✓ Detected perspective: ${perspective}`);
        break;
    }
}

console.log('Perspective:', detectedPerspective);


// ============================================
// BROAD QUERY DETECTION
// ============================================

function isBroadTourismQuery(query) {
    const lowerQuery = query.toLowerCase().trim();

    // ========== EXACT BROAD PHRASES ==========
    const exactBroadPhrases = [
        'tourist places', 'tourist place', 'tourism',
        'places to visit', 'visit kurukshetra', 'places to see',
        'what to see', 'where to go', 'places of interest',
        'tourist destination', 'places to explore',
        // Hindi
        'पर्यटन स्थल', 'पर्यटक स्थल', 'घूमने के स्थान',
        'दर्शनीय स्थल', 'देखने लायक', 'कहाँ जाएं', 'पर्यटन'
    ];

    // Check if query EXACTLY matches or CONTAINS broad phrase
    for (const phrase of exactBroadPhrases) {
        if (lowerQuery === phrase || lowerQuery.includes(phrase)) {
            console.log(`✓ Broad phrase matched: "${phrase}"`);
            return true;
        }
    }

    // ========== SPECIFIC SITES (NOT BROAD) ==========
    const specificSites = [
        'brahma sarovar', 'braham sarovar',
        'jyotisar', 'jyoti sar',
        'sthaneshwar', 'sthaneswar',
        'baan ganga', 'ban ganga',
        'sannihit', 'sanihit',
        'अनुभव', 'केंद्र',
        'यक्ष'
    ];

    // If mentions specific site, it's NOT broad
    for (const site of specificSites) {
        if (lowerQuery.includes(site)) {
            console.log(`✓ Specific site mentioned: "${site}" - NOT broad`);
            return false;
        }
    }

    // ========== GENERIC TERMS (MIGHT BE BROAD) ==========
    const genericTerms = ['places', 'sites', 'spots', 'attractions', 'स्थल'];
    const hasGenericTerm = genericTerms.some(term => lowerQuery.includes(term));

    if (hasGenericTerm && !lowerQuery.includes('specific')) {
        console.log('✓ Generic term without specific site - is broad');
        return true;
    }

    return false;
}

const isBroad = isTourism ? isBroadTourismQuery(message) : false;

console.log('Is Broad Tourism:', isBroad);
console.log('========================');


// ============================================
// RETURN DATA
// ============================================

return [{
    json: {
        message: message,
        language: language,
        isTourism: isTourism,
        isBroadTourism: isBroad,
        isPrivateBusiness: isPrivateBusiness,
        perspective: detectedPerspective  // ← NEW FIELD
    }
}];

// ========================================
// FIXED: Search Cache - Empty cache is OK!
// ========================================

// Get webhook data
const webhookNode = $('Webhook').first();
if (!webhookNode) {
    throw new Error('Webhook node not found');
}

const webhookBody = webhookNode.json?.body || {};
const userQuestion = webhookBody?.question || webhookBody?.message || '';
const userLanguage = webhookBody?.language || 'en';

// Validate question exists
if (!userQuestion) {
    return [{
        json: {
            cached: false,
            needsAI: false,  // ← Changed: No question is an error, not "needsAI"
            error: "No question provided",
            question: "",
            message: "",
            language: userLanguage
        }
    }];
}

// Get Google Sheets data (may be empty)
const allLogs = $input.all();

console.log(`📊 Cache records available: ${allLogs.length}`);

// ========================================
// EMPTY CACHE IS FINE! Just continue to web search
// ========================================
if (!allLogs || allLogs.length === 0) {
    console.log('ℹ️ Cache is empty (first time questions) - continuing to web search');

    return [{
        json: {
            question: userQuestion,
            message: userQuestion,
            cached: false,
            needsAI: false,  // ← FIXED: Empty cache doesn't mean "needsAI"
            similarQuestions: [],
            contextForAI: '',
            language: userLanguage,
            totalSimilarFound: 0,
            cacheStatus: "Cache empty - first query",
            source: 'no-cache-continue-search',
            // Pass through all webhook data
            ...webhookBody
        }
    }];
}

// ========================================
// HELPER FUNCTIONS
// ========================================

function normalizeText(text) {
    if (!text) return '';
    // FIXED: Convert to string first to handle numbers
    const str = String(text);
    return str.toLowerCase().trim()
        .replace(/[?!.,;:'"]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
}

function calculateSimilarity(str1, str2) {
    if (str1 === str2) return 1.0;

    const words1 = str1.split(' ').filter(w => w.length > 0);
    const words2 = str2.split(' ').filter(w => w.length > 0);

    if (words1.length === 0 || words2.length === 0) return 0;

    let matchCount = 0;
    for (const word of words1) {
        if (words2.includes(word)) matchCount++;
    }

    const totalUniqueWords = new Set([...words1, ...words2]).size;
    return matchCount / totalUniqueWords;
}

function levenshteinDistance(str1, str2) {
    const matrix = [];
    for (let i = 0; i <= str2.length; i++) matrix[i] = [i];
    for (let j = 0; j <= str1.length; j++) matrix[0][j] = j;

    for (let i = 1; i <= str2.length; i++) {
        for (let j = 1; j <= str1.length; j++) {
            if (str2[i - 1] === str1[j - 1]) {
                matrix[i][j] = matrix[i - 1][j - 1];
            } else {
                matrix[i][j] = Math.min(
                    matrix[i - 1][j - 1] + 1,
                    matrix[i][j - 1] + 1,
                    matrix[i - 1][j] + 1
                );
            }
        }
    }
    return matrix[str2.length][str1.length];
}

function fuzzyMatch(str1, str2) {
    const distance = levenshteinDistance(str1, str2);
    const maxLength = Math.max(str1.length, str2.length);
    return maxLength > 0 ? 1 - (distance / maxLength) : 0;
}

// ========================================
// SEARCH THROUGH CACHE
// ========================================

console.log(`🔍 Searching ${allLogs.length} cached records for: "${userQuestion}"`);

const normalizedUserQuestion = normalizeText(userQuestion);
const matches = [];

// Search through logs
for (const log of allLogs) {
    const logData = log.json;

    if (!logData.question || (!logData.answer && !logData.response)) continue;

    const logAnswer = logData.answer || logData.response || '';

    // Language matching
    if (logData.language && userLanguage) {
        const logLang = logData.language.toLowerCase();
        const userLang = userLanguage.toLowerCase();
        if (logLang !== userLang && 
            !(logLang.includes('hindi') && userLang.includes('hi')) &&
            !(logLang.includes('english') && userLang.includes('en'))) {
            continue;
        }
    }

    const normalizedLogQuestion = normalizeText(logData.question);
    const wordSimilarity = calculateSimilarity(normalizedUserQuestion, normalizedLogQuestion);
    const fuzzySimilarity = fuzzyMatch(normalizedUserQuestion, normalizedLogQuestion);
    const similarity = Math.max(wordSimilarity, fuzzySimilarity);

    if (similarity > 0.4) {
        matches.push({
            originalQuestion: logData.question,
            question: normalizedLogQuestion,
            answer: logAnswer,
            response: logAnswer,
            language: logData.language || userLanguage,
            similarity: similarity,
            timestamp: logData.Timestamp || logData.timestamp,
            response_id: logData.response_id  // ← ADD THIS LINE
        });
    }
}

matches.sort((a, b) => b.similarity - a.similarity);

console.log(`✅ Found ${matches.length} similar questions`);

// ========================================
// CHECK FOR CACHE HIT (>85% match) - STRICTER THRESHOLD
// ========================================

const exactMatch = matches.find(m => m.similarity > 0.85);  // Changed from 0.75

if (exactMatch) {
    console.log(`🎯 CACHE HIT! Similarity: ${(exactMatch.similarity * 100).toFixed(1)}%`);
    console.log(`   Matched: "${exactMatch.originalQuestion}"`);

    return [{
        json: {
            response: exactMatch.answer,
            source: 'cache',
            cached: true,
            similarity: exactMatch.similarity,
            question: userQuestion,
            message: userQuestion,
            language: exactMatch.language,
            success: true,
            matchedQuestion: exactMatch.originalQuestion,
            totalMatches: matches.length,
            response_id: exactMatch.response_id,
            ...webhookBody
        }
    }];
}

// ========================================
// CACHE MISS - Continue to web search
// ========================================

console.log(`❌ CACHE MISS - continuing to web search`);

const topMatches = matches.slice(0, 5);
let contextForAI = '';

if (topMatches.length > 0) {
    console.log(`📚 Providing ${topMatches.length} similar Q&As as context`);

    contextForAI = userLanguage === 'hi' 
        ? 'पिछले समान प्रश्न और उत्तर:\n\n'
        : 'Previous similar questions and answers:\n\n';

    topMatches.forEach((match, index) => {
        contextForAI += `${index + 1}. Q: ${match.originalQuestion}\n`;
        contextForAI += `   A: ${match.answer}\n`;
        contextForAI += `   (Similarity: ${(match.similarity * 100).toFixed(1)}%)\n\n`;
    });
}

// ========================================
// RETURN: Not cached, proceed to web search
// ========================================

return [{
    json: {
        question: userQuestion,
        message: userQuestion,
        cached: false,
        needsAI: false,  // ← FIXED: Cache miss doesn't mean "needsAI"
        similarQuestions: topMatches,
        contextForAI: contextForAI,
        language: userLanguage,
        totalSimilarFound: topMatches.length,
        bestMatchSimilarity: matches[0]?.similarity || 0,
        source: 'cache-miss-continue-search',
        ...webhookBody
    }
}];

// ========================================
// FIXED: Filter Valid URLs
// Handles both link field AND organic_results array
// ========================================

const data = $input.first().json;

console.log('=== Filter Valid URLs ===');
console.log('Input link:', data.link);
console.log('noResults:', data.noResults);
console.log('organic_results count:', data.organic_results?.length || 0);

// ========================================
// CASE 1: Already marked as no results
// ========================================
if (data.noResults === true && !data.link) {
    console.log('✓ Already marked as noResults, passing through');
    return [$input.first()];
}

// ========================================
// CASE 2: Direct link field is populated (from Code in JavaScript2)
// ========================================
if (data.link && data.link.trim() !== '') {
    const url = data.link.trim();

    console.log(`✓ Direct link found: ${url}`);

    // Check if it's a bad URL pattern - ENHANCED PATTERNS
    const skipPatterns = [
        // Dead/old sections (original)
        '/adhaun/', '/old/', '/archive/', '/404', '/error',

        // Technical/Downloads (NEW - usually forms, not info)
        '/downloads/', '/forms/', '/applications/', '/upload/',

        // Media galleries (NEW - not informational)
        '/gallery/', '/photo-gallery/', '/video-gallery/', '/images/',

        // Other irrelevant (NEW)
        '/events-calendar/', '/feedback/', '/contact-form/',
        '/guest-book/', '/sitemap/', '/search/', '/login/'
    ];

    const isBad = skipPatterns.some(pattern => url.toLowerCase().includes(pattern));

    if (isBad) {
        const matchedPattern = skipPatterns.find(p => url.toLowerCase().includes(p));
        console.log(`❌ Bad URL detected: ${url}`);
        console.log(`   Reason: Contains pattern "${matchedPattern}"`);
        console.log('   Will check organic_results for alternatives...');
        // Continue to check organic_results below
    } else {
        console.log(`✅ Valid URL, keeping it: ${url}`);
        // URL is good, keep it as-is
        return [{
            json: {
                ...data,
                link: url,
                noResults: false,
                filteredCount: 1,
                filterApplied: 'direct-link-validated'
            }
        }];
    }
}

// ========================================
// CASE 3: Check organic_results array
// ========================================
const allResults = data.organic_results || [];

if (allResults.length === 0) {
    console.log('❌ No organic_results to filter');
    return [{
        json: {
            ...data,
            link: '',
            noResults: true,
            organic_results: []
        }
    }];
}

console.log(`📊 Filtering ${allResults.length} organic results...`);

// Known bad URL patterns - ENHANCED (same as above)
const skipPatterns = [
    // Dead/old sections
    '/adhaun/', '/old/', '/archive/', '/404', '/error',

    // Education pages (NEW)
    '/class-0', '/class-1', '/class-2', '/class-3', '/class-4',
    '/class-5', '/class-6', '/class-7', '/class-8', '/class-9',
    '/syllabus/', '/curriculum/', '/examination/', '/results/',
    '/admission/', '/datesheet/',

    // HR/Administrative (NEW)
    '/recruitment/', '/vacancy/', '/tender/', '/bid/', '/auction/',
    '/circulars/', '/orders/', '/notification/', '/noc/',

    // Technical/Downloads (NEW)
    '/downloads/', '/forms/', '/applications/', '/upload/',

    // Media galleries (NEW)
    '/gallery/', '/photo-gallery/', '/video-gallery/', '/images/',

    // Other irrelevant (NEW)
    '/events-calendar/', '/feedback/', '/contact-form/',
    '/guest-book/', '/sitemap/', '/search/', '/login/'
];

// Good URL patterns (priority scores) - UNCHANGED
const goodPatterns = [
    { pattern: 'know-kurukshetra', score: 10 },
    { pattern: 'about-district', score: 10 },
    { pattern: 'services', score: 7 },
    { pattern: 'about-kurukshetra', score: 10 }
];

// Filter and score URLs
const validUrls = [];

for (const result of allResults) {
    const url = result.link || '';

    if (!url) continue;

    // Skip bad patterns
    const isBad = skipPatterns.some(pattern => 
        url.toLowerCase().includes(pattern)
    );

    if (isBad) {
        const matchedPattern = skipPatterns.find(p => url.toLowerCase().includes(p));
        console.log(`⏭️ Skipping bad URL: ${url}`);
        console.log(`   Reason: Contains pattern "${matchedPattern}"`);  // ← ENHANCED logging
        continue;
    }

    // Calculate priority score
    let score = 0;
    for (const good of goodPatterns) {
        if (url.toLowerCase().includes(good.pattern)) {
            score += good.score;
        }
    }

    // Prefer HTTPS
    if (url.startsWith('https://')) score += 1;

    // Prefer shorter URLs
    const pathDepth = url.split('/').length;
    if (pathDepth <= 5) score += 2;

    validUrls.push({
        ...result,
        link: url,
        priorityScore: score
    });
}

// Sort by priority
validUrls.sort((a, b) => b.priorityScore - a.priorityScore);

console.log(`✅ Filtered: ${validUrls.length} valid URLs (from ${allResults.length})`);

// ========================================
// RETURN RESULT
// ========================================
if (validUrls.length === 0) {
    console.log('❌ No valid URLs found after filtering');
    return [{
        json: {
            ...data,
            link: '',
            noResults: true,
            organic_results: [],
            filterApplied: 'all-urls-filtered-out'
        }
    }];
}

// Return with BEST URL as primary link
