// DEMOGRAPHIC DATA EXTRACTOR (SAFE VERSION)
// Forcefully extracts census data from scraped content
// ============================================

const scrapedText = $input.first().json.text || '';

// Safely get queryCategory with fallback
let queryCategory = 'general';
try {
    const enhancer = $('Smart_Query_Enhancer').first();
    if (enhancer && enhancer.json && enhancer.json.queryCategory) {
        queryCategory = enhancer.json.queryCategory;
    }
} catch (e) {
    console.log('Smart_Query_Enhancer not found, using fallback');
    // Try to get from input instead
    queryCategory = $input.first().json.queryCategory || 'general';
}

console.log('=== Demographic Data Extractor ===');
console.log('Query Category:', queryCategory);

let extractedData = {
    population: null,
    sexRatio: null,
    literacyRate: null,
    density: null,
    growthRate: null
};

// Only extract if this is a demographic query
if (queryCategory === 'demographic') {
    console.log('Extracting demographic data...');

    // Extract Population
    const popMatch = scrapedText.match(/population of ([\d,]+)/i);
    if (popMatch) {
        extractedData.population = popMatch[1];
        console.log('✓ Found population:', extractedData.population);
    }

    // Extract Sex Ratio (multiple patterns)
    const sexRatioPatterns = [
        /sex ratio of (\d+) females/i,
        /(\d+) females for every 1000 males/i,
        /sex ratio[^\d]*(\d+)/i
    ];

    for (const pattern of sexRatioPatterns) {
        const match = scrapedText.match(pattern);
        if (match) {
            extractedData.sexRatio = match[1];
            console.log('✓ Found sex ratio:', extractedData.sexRatio);
            break;
        }
    }

    // Extract Literacy Rate
    const literacyMatch = scrapedText.match(/literacy rate of ([\d.]+)%/i);
    if (literacyMatch) {
        extractedData.literacyRate = literacyMatch[1];
        console.log('✓ Found literacy rate:', extractedData.literacyRate);
    }

    // Extract Density
    const densityMatch = scrapedText.match(/density of (\d+) inhabitants/i);
    if (densityMatch) {
        extractedData.density = densityMatch[1];
        console.log('✓ Found density:', extractedData.density);
    }

    // Extract Growth Rate
    const growthMatch = scrapedText.match(/growth rate[^\d]*([\d.]+)%/i);
    if (growthMatch) {
        extractedData.growthRate = growthMatch[1];
        console.log('✓ Found growth rate:', extractedData.growthRate);
    }
}

