    .replace(/\s+/g, ' ') // Remove extra double spaces left behind by deleted emojis
    .trim();

console.log('Original:', text);
console.log('Cleaned:', cleanText);

// 4. Return data, promoting variables to the top level so the next nodes can easily read them
return [{
    json: {
        ...data,
        ...payload, // Brings 'city', 'language', etc., to the top level
        message: cleanText,
